def rowJMFFD (n j : ℕ) : Polynomial ℤ :=
 ∑ s ∈ range (j+1), C (((j+3).choose (j-s):ℤ)*((n-j-1).choose s:ℤ))*
   X^s*(X+1)^(j-s)

def rowDiscMFFD (f : ℕ → Polynomial ℤ) (j : ℕ) : Polynomial ℤ :=
 f j+2*rowShiftMFFD 1 0 f j-2*rowShiftMFFD 0 1 f j+
 rowShiftMFFD 2 0 f j+2*rowShiftMFFD 1 1 f j+rowShiftMFFD 0 2 f j

def rowJQMFFD (n : ℚ) (j : ℕ) : Polynomial ℚ :=
 ∑ s ∈ range (j+1), C (((j+3).choose (j-s):ℚ)*choosePolyM0D3 (n-j-1) s)*
   X^s*(X+1)^(j-s)
